1461	    /// The approval panel's keys. `y` approves, `n` denies, `a` asks to approve every later action (`a` or Enter
1462	    /// again confirms), Enter takes the focused option, ←/→ and Tab/Shift+Tab move the focus, Esc denies. Other text
1463	    /// goes to the draft (steering), so nothing typed is lost and the letters keep answering the panel.
1464	    fn on_approval_key(&mut self, key: KeyEvent, now: Instant) -> Option<Action> {
