1483	        let last = APPROVAL_OPTIONS.len() - 1;
1484	        let moved = match key.code {
1485	            KeyCode::Left if bare => Some(at.saturating_sub(1)),
1486	            KeyCode::Right if bare => Some((at + 1).min(last)),
1487	            KeyCode::Tab if bare => Some((at + 1) % APPROVAL_OPTIONS.len()),
1488	            KeyCode::BackTab if letter => Some((at + last) % APPROVAL_OPTIONS.len()),
1489	            _ => None,
1490	        };
1491	        if let Some(to) = moved {
1492	            approval.focus = APPROVAL_OPTIONS[to];
1493	            approval.confirming = false;
1494	            return None;
1495	        }
