1497	            KeyCode::Enter if bare => approval.focus,
1498	            KeyCode::Char('y' | 'Y') if letter => Verdict::Approved,
1499	            KeyCode::Char('n' | 'N') if letter => Verdict::Denied,
1500	            KeyCode::Char('a' | 'A') if letter => Verdict::ApprovedForSession,
1501	            // Not an answer. Typed text goes to the draft, where it is kept for after the decision (or sent as
1502	            // steering); it cancels a pending confirmation.
1503	            KeyCode::Char(c) if letter => {
