1516	        };
1517	        // In a run of typing a `y`, `n` or `a` is a letter of the text (kept in the draft) and Enter is ignored: only
1518	        // a key after a pause answers.
1519	        if approval.last_text.is_some_and(|at| now.saturating_duration_since(at) < APPROVAL_TYPING_RUN) {
1520	            approval.confirming = false;
1521	            // An ignored key re-arms the run, and the wait for a full repeat window: a held key (auto-repeat arrives
1522	            // as presses) stays inert until released.
1523	            approval.last_text = Some(now);
1524	            approval.rearm_guard(now);
