1537	            // Re-armed for a full repeat window by every ignored key: a key pressed and held inside the wait is not
1538	            // answered by its own first auto-repeat (up to about a second after the press); only a fresh press after
1539	            // the key has been quiet that long answers.
1540	            approval.rearm_guard(now);
