1547	            return None;
1548	        }
1549	        // A command that is cut off at the fold is never approved unseen.
1550	        if verdict != Verdict::Denied && !approval.read_all {
1551	            approval.notice = Some(APPROVAL_UNSEEN);
1552	            approval.rearm_guard(now);
