1554	        }
1555	        // Approving every later action is never one key: it asks once, then Enter or `a` confirms, no sooner than
1556	        // `APPROVAL_CONFIRM_DELAY` after the question (a double tap or held key does not).
1557	        if verdict == Verdict::ApprovedForSession {
1558	            if !approval.confirming {
1559	                approval.focus = Verdict::ApprovedForSession;
1560	                approval.confirming = true;
1561	                approval.confirm_asked_at = Some(now);
