1573	    /// Records the decision on the open approval and returns the command that answers it.
1574	    fn decide(&mut self, verdict: Verdict) -> Option<Action> {
1575	        let Some(Overlay::Approval(approval)) = self.overlay.take() else {
1576	            return None;
1577	        };
1578	        let insert_idx = self.transcript.iter().rposition(|e| match e {
1579	            Entry::Tool { tool, status: ToolStatus::Running, .. } => *tool == approval.tool,
1580	            _ => false,
1581	        });
1582	        let decision_entry = Entry::Decision {
1583	            tool: approval.tool,
1584	            subject: approval.subject,
1585	            verdict,
1586	        };
1587	        match insert_idx {
1588	            Some(idx) => self.transcript.insert(idx, decision_entry),
1589	            None => self.transcript.push(decision_entry),
1590	        };
1591	        Some(Action::Send(match verdict {
1592	            Verdict::Denied => Command::Deny { id: approval.id },
1593	            verdict => Command::Approve {
1594	                id: approval.id,
1595	                always: verdict == Verdict::ApprovedForSession,
1596	            },
1597	        }))
1598	    }
