565	/// Draws the approval panel: what is proposed and on what, the change itself (file changes through the shared diff
566	/// view), and the three decisions as buttons with the focused one highlighted. Returns the review's rows and the
567	/// largest useful scroll.
568	fn render_approval(frame: &mut Frame, area: Rect, approval: &Approval, depth: theme::Depth, waiting: usize, layout: &mut LiveLayout) {
569	    let pal = diff_view::palette(depth);
570	    let key = Style::default().fg(ACCENT).add_modifier(Modifier::BOLD);
571	    let muted = Style::default().fg(MUTED);
572	    let width = usize::from(area.width.saturating_sub(2));
573	    let narrow = width < 60;
574	    // What is proposed, and the target.
575	    let mut head = markdown::wrap(
576	        vec![
577	            Span::styled(diff_view::approval_safe_text(&tool_verb(&approval.tool)), Style::default().fg(Color::White).add_modifier(Modifier::BOLD)),
578	            Span::styled(format!(" {}", diff_view::approval_safe_text(&approval.subject)), Style::default().fg(Color::White)),
579	        ],
580	        width,
581	        Vec::new(),
582	        vec![Span::raw("  ")],
583	    );
584	    let kind = match &approval.patch {
585	        Some(patch) => patch.files.first().map(|file| {
586	            let (added, removed) = file.counts();
587	            format!("{} {} · +{added} {}{removed}", match file.status {
588	                diff_view::Status::Added => "create",
589	                diff_view::Status::Deleted => "delete",
590	                _ => "change",
591	            }, diff_view::approval_safe_text(file.path()), diff_view::MINUS)
592	        }),
593	        None if approval.tool == "run_command" => Some("run a shell command in the workspace".to_string()),
594	        None => None,
595	    };
596	    if let Some(kind) = kind {
597	        head.extend(markdown::wrap(vec![Span::styled(format!("Proposed: {kind}"), muted)], width, Vec::new(), vec![Span::raw("  ")]));
598	    }
599	    // The decisions, as buttons, each with the key that answers it; the focused one (what Enter takes) highlighted.
600	    let button = |label: &str, verdict: Verdict, hotkey: &str| -> Vec<Span<'static>> {
601	        let focused = approval.focus == verdict;
602	        let style = if focused {
603	            Style::default().fg(Color::Black).bg(ACCENT).add_modifier(Modifier::BOLD)
604	        } else {
605	            Style::default().fg(Color::White).bg(SURFACE)
606	        };
607	        let marker = if focused { "▸" } else { " " };
608	        vec![Span::styled(format!("{marker}{hotkey} {label} "), style), Span::raw(" ")]
609	    };
610	    let mut buttons = Vec::new();
611	    buttons.extend(button("Approve", Verdict::Approved, "y"));
612	    buttons.extend(button(if narrow { "All later" } else { "Approve all later actions" }, Verdict::ApprovedForSession, "a"));
613	    buttons.extend(button("Deny", Verdict::Denied, "n"));
614	    let mut footer = markdown::wrap(buttons, width, Vec::new(), Vec::new());
615	    // The line under the buttons: what answers the panel, or the question being asked (confirming), or why a key did
616	    // not answer. Each state has variants from long to short; the first that fits in one row is used, else the shortest
617	    // wraps. The panel always reserves the rows the default and the confirm line need, so asking the question or
618	    // showing a notice never moves the change or makes the panel stop being answerable.
619	    let default_hint = pick_hint(
620	        vec![
621	            vec![
622	                Span::styled("y", key),
623	                Span::styled(" approve · ", muted),
624	                Span::styled("n", key),
625	                Span::styled(" deny · ", muted),
626	                Span::styled("←→", key),
627	                Span::styled("/", muted),
628	                Span::styled("tab", key),
629	                Span::styled(" move, ", muted),
630	                Span::styled("enter", key),
631	                Span::styled(" takes ▸ · ", muted),
632	                Span::styled("↑↓", key),
633	                Span::styled(" scroll · ", muted),
634	                Span::styled("esc", key),
635	                Span::styled(" denies", muted),
636	            ],
637	            vec![Span::styled("y", key), Span::styled("/", muted), Span::styled("n", key), Span::styled(" or ", muted), Span::styled("←→ enter", key), Span::styled(" · ", muted), Span::styled("esc", key), Span::styled(" denies", muted)],
638	        ],
639	        width,
640	    );
641	    let ask = Style::default().fg(Color::Yellow);
642	    let confirm_hint = pick_hint(
643	        vec![
644	            vec![
645	                Span::styled("approve this and every later action (switches to auto)? ", ask),
646	                Span::styled("enter", key),
647	                Span::styled(" confirms · ", muted),
648	                Span::styled("←→", key),
649	                Span::styled(" back · ", muted),
650	                Span::styled("esc", key),
651	                Span::styled(" denies", muted),
652	            ],
653	            vec![Span::styled("approve all later actions? ", ask), Span::styled("enter", key), Span::styled(" confirms · ", muted), Span::styled("esc", key), Span::styled(" denies", muted)],
654	            vec![Span::styled("approve all later? ", ask), Span::styled("enter", key), Span::styled(" confirms · ", muted), Span::styled("esc", key), Span::styled(" denies", muted)],
655	            vec![Span::styled("enter", key), Span::styled(" confirms all · ", muted), Span::styled("esc", key), Span::styled(" denies", muted)],
656	        ],
657	        width,
658	    );
659	    let wrap_hint = |spans: Vec<Span<'static>>| markdown::wrap(spans, width, Vec::new(), Vec::new());
660	    let hint_rows = wrap_hint(default_hint.clone()).len().max(wrap_hint(confirm_hint.clone()).len());
661	    // The question stays on screen for as long as it is pending, whatever key was ignored meanwhile.
662	    let mut hint = match approval.notice {
663	        _ if approval.confirming => wrap_hint(confirm_hint),
664	        // A key did not answer: say which and why, instead of silently doing nothing.
665	        Some(notice) => wrap_hint(pick_hint(
666	            vec![vec![Span::styled(notice, ask)], vec![Span::styled(notice.split(" — ").next().unwrap_or(notice), ask)]],
667	            width,
668	        )),
669	        None => wrap_hint(default_hint),
670	    };
671	    hint.truncate(hint_rows);
672	    hint.resize(hint_rows, Line::default());
673	    let lines: Vec<Line> = match &approval.patch {
674	        Some(patch) => {
675	            let geo = Geometry { width, indent: 1, num_width: diff_view::patch_num_width(patch) };
676	            diff_view::panel_rows(patch)
677	                .into_iter()
678	                .filter(|row| !matches!(row, diff_view::Row::File(_) | diff_view::Row::Blank))
679	                .flat_map(|row| diff_view::panel_row_lines(patch, row, geo, Fit::Wrap, &pal))
680	                .collect()
681	        }
682	        // Text rows (commands, scripts, arguments) wrap to the panel so no part of a line is cut off at its edge.
683	        None => approval
684	            .lines
685	            .iter()
686	            .flat_map(|line| markdown::wrap(vec![Span::styled(line.text.clone(), line_style(line.kind))], width, Vec::new(), vec![Span::raw("    ")]))
687	            .collect(),
688	    };
689	    // The panel fits its content (heading, the change, decisions, the hint rows) and never needs more than the area. What
690	    // must be drawn for the panel to count as shown, in order: the heading, the buttons, the hint rows, and the change
691	    // (a text that must be folded needs two body rows: one row and the fold marker). The gap rows come last.
692	    let available = usize::from(area.height.saturating_sub(2));
693	    let body_min = if lines.len() > 1 { 2 } else { usize::from(!lines.is_empty()) };
694	    let fits = available >= head.len() + footer.len() + hint_rows + body_min;
695	    if fits {
696	        footer.extend(hint);
697	    } else {
698	        // Nothing to answer: only the refusal, kept where the operator looks for the decisions.
699	        footer = markdown::wrap(
700	            vec![Span::styled(
701	                ["enlarge the terminal to see the proposed change · esc denies", "enlarge the terminal · esc denies", "enlarge the terminal"]
702	                    .into_iter()
703	                    .find(|text| unicode_width::UnicodeWidthStr::width(*text) <= width)
704	                    .unwrap_or("enlarge terminal"),
705	                Style::default().fg(Color::Yellow),
706	            )],
707	            width,
708	            Vec::new(),
709	            Vec::new(),
710	        );
711	    }
712	    let gaps = usize::from(fits && available >= head.len() + footer.len() + 2 + body_min);
713	    let body_room = available.saturating_sub(head.len() + footer.len() + gaps * 2);
714	    let rows = lines.len().min(body_room);
715	    let height = (head.len() + footer.len() + gaps * 2 + rows + 2).min(usize::from(area.height));
716	    let rect = Rect { height: u16::try_from(height).unwrap_or(area.height), ..area };
717	    // More requests queued behind this one: say so, so a repeated key is not mistaken for answering the same one.
718	    let mut block = modal_block(" Approval needed ");
719	    if waiting > 0 {
720	        block = block.title(Span::styled(format!(" {waiting} more waiting "), Style::default().fg(Color::Yellow)));
721	    }
722	    let inner = block.inner(rect);
723	    frame.render_widget(Clear, rect);
724	    frame.render_widget(block, rect);
725	    // The decisions (or the refusal) take their rows before the heading does.
726	    let footer_rows = u16::try_from(footer.len()).unwrap_or(0).min(inner.height);
727	    let head_rows = u16::try_from(head.len()).unwrap_or(0).min(inner.height - footer_rows);
728	    let gap = u16::try_from(gaps).unwrap_or(0);
729	    let body = Rect {
730	        y: inner.y + head_rows + gap,
731	        height: inner.height.saturating_sub(head_rows + footer_rows + gap * 2),
732	        ..inner
733	    };
734	    // Text that does not fit keeps its last body row for the fold marker, so the marker never takes a row of the text
735	    // and `limit` (what must be scrolled through before approving) counts only rows that can be seen.
736	    let folded = lines.len() > usize::from(body.height);
737	    let viewport = usize::from(body.height).saturating_sub(usize::from(folded));
738	    let limit = lines.len().saturating_sub(viewport);
739	    // Shown means: the heading, the decisions, the hint rows and at least one row of the change (when there is one) are
740	    // on screen.
741	    let drawn = fits && usize::from(head_rows) == head.len() && usize::from(footer_rows) == footer.len() && (lines.is_empty() || viewport >= 1);
742	    let top = approval.scroll.min(limit);
743	    let total = lines.len();
744	    let mut shown: Vec<Line> = lines.into_iter().skip(top).take(viewport).collect();
745	    if folded && viewport >= 1 {
746	        let below = limit - top;
747	        let marker = match (below, width) {
748	            (0, _) => "end of change · ↑ scrolls back".to_string(),
749	            (_, ..44) => format!("↓ {below} more · ↓ reads on"),
750	            (_, 44..) => format!("↓ {below} more rows below · ↓ reads on"),
751	        };
752	        shown.push(Line::from(Span::styled(marker, Style::default().fg(Color::Yellow))));
753	    }
754	    frame.render_widget(Paragraph::new(head), Rect { height: head_rows, ..inner });
755	    frame.render_widget(Paragraph::new(shown), body);
756	    frame.render_widget(Paragraph::new(footer), Rect { y: inner.y + inner.height - footer_rows, height: footer_rows, ..inner });
757	    layout.overlay_rows = viewport;
758	    layout.overlay_limit = limit;
759	    layout.approval_drawn = drawn;
760	    layout.approval_total = total;
761	    layout.approval_top = top;
762	    layout.approval_seen_to = (top + viewport).min(total);
763	    layout.approval_width = width;
764	    layout.approval_body = body;
765	}
