767	/// The first of `variants` (longest first) whose text fits `width` columns; the last (shortest) when none does.
768	fn pick_hint(mut variants: Vec<Vec<Span<'static>>>, width: usize) -> Vec<Span<'static>> {
769	    let fits = |spans: &Vec<Span<'static>>| spans.iter().map(|span| unicode_width::UnicodeWidthStr::width(span.content.as_ref())).sum::<usize>() <= width;
770	    let at = variants.iter().position(fits).unwrap_or(variants.len() - 1);
771	    variants.swap_remove(at)
772	}
