774	fn line_style(kind: LineKind) -> Style {
775	    match kind {
776	        LineKind::Added => Style::default().fg(Color::Green),
777	        LineKind::Removed => Style::default().fg(Color::Red),
778	        LineKind::Hunk => Style::default().fg(Color::Cyan),
779	        LineKind::Meta => Style::default().fg(MUTED),
780	        LineKind::Command => Style::default()
781	            .fg(Color::White)
782	            .add_modifier(Modifier::BOLD),
783	        LineKind::Context => Style::default().fg(Color::White),
784	    }
