787	/// How a row of a command's `diff` output is coloured: rows that are not part of a hunk read as headers.
788	fn diff_row_kind(row: &str) -> LineKind {
789	    if row.starts_with('+') && !row.starts_with("+++") {
790	        LineKind::Added
791	    } else if row.starts_with('-') && !row.starts_with("---") {
792	        LineKind::Removed
793	    } else if row.starts_with("@@") {
794	        LineKind::Hunk
795	    } else if row.starts_with(' ') {
796	        LineKind::Context
797	    } else {
798	        LineKind::Meta
799	    }
800	}
