            if matches!(self.overlay, Some(Overlay::Paste { .. })) && key.code == KeyCode::Char('x') && ctrl {
                self.overlay = None;
                self.composer.expand_paste_at_cursor();
                return None;
            }
            self.on_help_key(key);
            return None;

