1	//! Sweep of the approval panel's whole state space. Every combination of review kind, terminal size, draft and queue
2	//! is drawn, and the invariants that make the panel safe to answer are asserted on what reached the screen:
3	//!
4	//! - (a) nothing panics, no row is wider than the terminal, the change's rows stay inside it;
5	//! - (b) the panel counts as answerable only when its buttons and hint were drawn, and `y` approves only after every row
6	//!   of the change was drawn in some frame; asking to approve all later actions is confirmed only after the question
7	//!   was drawn;
8	//! - (c) a terminal too small to draw it refuses with "enlarge the terminal" and Esc still denies; one that is big
9	//!   enough for a one-line command is never refused (and what is answerable at one height is at every greater height);
10	//! - (d) no cell of the screen holds a control, bidi, tag, zero-width or blank-looking character;
11	//! - (e) a burst of keys never answers.
12	use super::*;
13	use crate::live_state::{Action, LiveLayout, LiveState, Overlay};
14	use crate::protocol::{Command, parse_event};
15	use crossterm::event::{KeyCode, KeyEvent, KeyModifiers};
16	use ratatui::{Terminal, backend::TestBackend};
17	use std::collections::BTreeMap;
18	use std::time::{Duration, Instant};
19	
20	const HELLO: &str = r#"{"v":1,"type":"hello","protocol":1,"pid":1}"#;
21	const BUSY: &str = r#"{"v":1,"type":"session.state","workspace":"/w/app","workspace_name":"app","model":"m","mode":"auto","git":null,"busy":true}"#;
22	
23	/// What a cell must never hold, listed independently of the predicate the panel uses: controls, bidi and format
24	/// characters, tag characters, zero-width and blank-looking characters.
25	fn forbidden(c: char) -> bool {
26	    let code = c as u32;
27	    c.is_control()
28	        || matches!(code,
29	            0xa0 | 0xad | 0x34f | 0x61c | 0x115f | 0x1160 | 0x1680 | 0x17b4..=0x17b5 | 0x180b..=0x180f | 0x2000..=0x200f | 0x2028..=0x202f
30	            | 0x205f..=0x206f | 0x2800 | 0x3000 | 0x3164 | 0xfe00..=0xfe0f | 0xfeff | 0xffa0 | 0xfff9..=0xfffb | 0x1d173..=0x1d17a
31	            | 0xe0000..=0xe0fff)
32	}
33	
34	/// One of every kind of character `forbidden` lists.
35	fn bad() -> String {
36	    let mut out = String::new();
37	    for code in [0x1b, 0x0d, 0x7f, 0x85, 0x9f, 0xa0, 0xad, 0x34f, 0x61c, 0x115f, 0x1160, 0x1680, 0x17b4, 0x180b, 0x180e, 0x2800, 0x3000, 0x3164, 0xfeff, 0xffa0, 0xe0001]
38	        .into_iter()
39	        .chain(0x2000..=0x200f)
40	        .chain(0x2028..=0x202f)
41	        .chain(0x205f..=0x206f)
42	        .chain(0xfe00..=0xfe0f)
43	        .chain(0xfff9..=0xfffb)
44	        .chain(0x1d173..=0x1d17a)
45	        .chain(0xe0020..=0xe007f)
46	        .chain(0xe0100..=0xe0102)
47	    {
48	        out.push(char::from_u32(code).unwrap());
49	    }
50	    out
51	}
