53	#[derive(Clone)]
54	struct Kind {
55	    name: &'static str,
56	    tool: String,
57	    subject: String,
58	    review: serde_json::Value,
59	    /// Short strings that must reach the screen (in some frame) before the change counts as read.
60	    tokens: Vec<String>,
61	}
62	
63	fn kinds(bad: &str) -> Vec<Kind> {
64	    let kind = |name, tool: &str, subject: &str, review: serde_json::Value, tokens: &[&str]| Kind {
65	        name,
66	        tool: tool.to_string(),
67	        subject: format!("{subject}{bad}"),
68	        review,
69	        tokens: tokens.iter().map(|token| token.to_string()).collect(),
70	    };
71	    let numbered = |prefix: &str, count: usize| (0..count).map(|n| format!("{prefix}{n:02}\n")).collect::<String>();
72	    let long_command = format!("echo {}ZZTAIL{bad}", (0..30).map(|n| format!("word{n} ")).collect::<String>());
73	    vec![
74	        kind("command", "run_command", "echo ok", serde_json::json!({"kind": "command", "command": format!("echo ok{bad}")}), &["echook"]),
75	        kind("command multi", "run_command", "deploy", serde_json::json!({"kind": "command", "command": format!("{}echo end{bad}", numbered("echo qa", 8))}), &["echoqa00", "echoqa07", "echoend"]),
76	        kind("command long", "run_command", "x", serde_json::json!({"kind": "command", "command": long_command}), &["ZZTAIL"]),
77	        kind("verifier", "run_tests", "npm test", serde_json::json!({"kind": "verifier", "command": format!("npm test{bad}"), "script": format!("echo qv1\nqv2{bad}"), "detail": format!("qv3{bad}")}), &["npmtest", "qv1", "qv2", "qv3"]),
78	        kind("args", "fetch_web", "x", serde_json::json!({"kind": "args", "text": format!("qw1\nqw2{bad}\nqw3"), "truncated": true}), &["qw1", "qw2", "qw3", "previewtruncated"]),
79	        kind("create", "write_file", "a.txt", serde_json::json!({"kind": "change", "path": format!("a{bad}.txt"), "before": null, "after": format!("{}z{bad}", numbered("qc", 12)), "created": true, "truncated": false}), &["qc00", "qc05", "qc11"]),
80	        kind("create empty", "write_file", "a.txt", serde_json::json!({"kind": "change", "path": format!("a{bad}.txt"), "before": null, "after": "", "created": true, "truncated": false}), &["nochanges"]),
81	        kind("identical", "write_file", "a.txt", serde_json::json!({"kind": "change", "path": format!("a{bad}.txt"), "before": "same\n", "after": "same\n", "created": false, "truncated": false}), &["nochanges"]),
82	        kind("edit", "write_file", "a.txt", serde_json::json!({"kind": "change", "path": "a.txt", "before": format!("a\nb{bad}\nc\n"), "after": format!("a\nqe1{bad}\nc\n"), "created": false, "truncated": false}), &["qe1"]),
83	        kind("patch", "patch_file", "x", serde_json::json!({"kind": "patch", "path": "x", "patch": format!("--- a/x\n+++ b/x\n@@ -1,2 +1,2 @@ sec{bad}\n-qp1{bad}\n+qp2{bad}\n qp3"), "truncated": false}), &["qp1", "qp2", "qp3"]),
84	        kind("patch miscounted", "patch_file", "x", serde_json::json!({"kind": "patch", "path": "x", "patch": format!("--- a/x\n+++ b/x\n@@ -1,1 +1,1 @@\n-qm1{bad}\n+qm2\n-qm3\n+qm4"), "truncated": false}), &["qm1", "qm2", "qm3", "qm4"]),
85	        kind("patch two files", "patch_file", "x", serde_json::json!({"kind": "patch", "path": "x", "patch": format!("--- a/x\n+++ b/x\n@@ -1 +1 @@\n-qn1\n+qn2\n--- a/y\n+++ b/y\n@@ -1 +1 @@\n-qn3{bad}\n+qn4"), "truncated": false}), &["qn1", "qn2", "qn3", "qn4"]),
86	        kind("patch no hunks", "patch_file", "x", serde_json::json!({"kind": "patch", "path": "x", "patch": format!("--- a/x\n+++ b/x\nBinary files differ{bad}"), "truncated": false}), &["Binaryfiles"]),
87	        kind("unknown tool", "zap_things", "x", serde_json::json!({"kind": "args", "text": format!("qz1{bad}"), "truncated": false}), &["qz1"]),
88	        kind("future kind", "zap_things", "x", serde_json::json!({"kind": "future-kind"}), &["Thisrequesthasnopreview"]),
89	    ]
90	}
91	
92	fn request(kind: &Kind, id: &str) -> String {
93	    serde_json::json!({"v": 1, "type": "approval.request", "id": id, "turn_id": "t1", "tool": kind.tool, "subject": kind.subject, "preview": "", "review": kind.review}).to_string()
94	}
95	
96	fn build(kind: &Kind, draft: &str, queued: bool) -> LiveState {
97	    let mut state = LiveState::new();
98	    for line in [HELLO, BUSY, request(kind, "a1").as_str()] {
99	        state.apply(parse_event(line).unwrap());
100	    }
101	    if queued {
102	        state.apply(parse_event(&request(kind, "a2")).unwrap());
103	    }
104	    state.composer.insert(draft);
105	    state
106	}
107	
108	struct Frame {
109	    /// The notice and the question as the frame drew them (the frame's own `note_layout` may clear them after).
110	    notice: Option<&'static str>,
111	    confirming: bool,
112	    rows: Vec<String>,
113	    layout: LiveLayout,
114	    terminal: Terminal<TestBackend>,
115	}
116	
117	/// How a frame is drawn: the whole screen (composer, status and all), or the panel alone in a rectangle of that size
118	/// (cheap, so every panel height can be swept).
119	#[derive(Clone, Copy, PartialEq)]
120	enum Mode {
121	    Screen,
122	    Panel,
123	}
124	
125	fn draw(state: &mut LiveState, width: u16, height: u16, mode: Mode) -> Frame {
126	    let mut terminal = Terminal::new(TestBackend::new(width, height)).unwrap();
127	    let mut layout = LiveLayout::default();
128	    let (notice, confirming) = match &state.overlay {
129	        Some(Overlay::Approval(approval)) => (approval.notice, approval.confirming),
130	        _ => (None, false),
131	    };
132	    terminal
133	        .draw(|frame| match (mode, &state.overlay) {
134	            (Mode::Panel, Some(Overlay::Approval(approval))) => render_approval(frame, frame.area(), approval, state.depth, state.approvals_waiting(), &mut layout),
135	            _ => layout = render_live(frame, state),
136	        })
137	        .unwrap();
138	    state.note_layout(layout);
139	    let buffer = terminal.backend().buffer();
140	    let rows = (0..height).map(|y| (0..width).map(|x| buffer[(x, y)].symbol()).collect::<String>()).collect();
141	    Frame { notice, confirming, rows, layout, terminal }
142	}
143	
144	/// A row's text without spaces and panel borders, so wrapped text compares by its characters.
145	fn flat(text: &str) -> String {
146	    text.chars().filter(|c| !c.is_whitespace() && *c != '│').collect()
147	}
148	
149	fn answerable(state: &LiveState) -> bool {
150	    matches!(&state.overlay, Some(Overlay::Approval(approval)) if approval.shown)
151	}
152	
153	fn key(code: KeyCode) -> KeyEvent {
154	    KeyEvent::new(code, KeyModifiers::NONE)
155	}
156	
157	fn is_approve(action: &Option<Action>, always: bool) -> bool {
158	    matches!(action, Some(Action::Send(Command::Approve { always: a, .. })) if *a == always)
159	}
160	
161	/// What a frame of an answerable panel must show: the three buttons and the hint (the question when confirming).
162	fn check_answerable_frame(frame: &Frame, tag: &str, out: &mut Vec<String>) {
163	    let all = flat(&frame.rows.join(""));
164	    if !frame.layout.approval_drawn {
165	        out.push(format!("{tag}: answerable but the frame did not draw it"));
166	    }
167	    for needed in ["Approve", "Deny"] {
168	        if !all.contains(needed) {
169	            out.push(format!("{tag}: answerable without {needed} drawn"));
170	        }
171	    }
172	    if !all.contains("Alllater") && !all.contains("Approvealllateractions") {
173	        out.push(format!("{tag}: answerable without the approve-all button drawn"));
174	    }
175	    if frame.confirming {
176	        if !all.contains("confirms") || !all.contains("all") {
177	            out.push(format!("{tag}: confirming without the question drawn"));
178	        }
179	    } else if let Some(notice) = frame.notice {
180	        let head: String = flat(notice.split(" — ").next().unwrap_or(notice)).chars().take(10).collect();
181	        if !all.contains(&head) {
182	            out.push(format!("{tag}: the notice {notice:?} was not drawn"));
183	        }
184	    }
185	    if frame.notice.is_none() && !all.contains("denies") {
186	        out.push(format!("{tag}: answerable without the Esc hint drawn"));
187	    }
188	}
189	
190	/// Reads the rows of the change the frame drew into `doc`, by their index in the change.
191	fn record(doc: &mut BTreeMap<usize, String>, frame: &Frame) {
192	    let layout = frame.layout;
193	    let buffer = frame.terminal.backend().buffer();
194	    for row in 0..layout.overlay_rows {
195	        let y = layout.approval_body.y + u16::try_from(row).unwrap();
196	        let text: String = (layout.approval_body.x..layout.approval_body.right()).map(|x| buffer[(x, y)].symbol()).collect();
197	        doc.insert(layout.approval_top + row, text);
198	    }
199	}
200	
201	#[derive(Clone, Copy, PartialEq)]
202	enum Finish {
203	    Approve,
204	    ApproveAll,
205	}
206	
207	/// Reads the change a page at a time, pressing the decision key between pages, until it answers. Returns the
208	/// violations found.
209	fn read_through(kind: &Kind, draft: &str, queued: bool, width: u16, height: u16, mode: Mode, finish: Finish, tag: &str) -> Vec<String> {
210	    let mut out = Vec::new();
211	    let t0 = Instant::now();
212	    let mut state = build(kind, draft, queued);
213	    let mut frame = draw(&mut state, width, height, mode);
214	    if !answerable(&state) {
215	        return out;
216	    }
217	    let mut doc = BTreeMap::new();
218	    let mut clock = 0u64;
219	    let at = |ms: u64| t0 + Duration::from_millis(ms);
220	    for step in 0..80 {
221	        let tag = format!("{tag} step {step}");
222	        check_answerable_frame(&frame, &tag, &mut out);
223	        record(&mut doc, &frame);
224	        let read = {
225	            let all: String = doc.values().map(|row| flat(row)).collect();
226	            kind.tokens.iter().all(|token| all.contains(token.as_str()))
227	        };
228	        let complete = matches!(&state.overlay, Some(Overlay::Approval(approval)) if approval.read_all);
229	        if complete {
230	            if !read {
231	                out.push(format!("{tag}: counted as read before every row was drawn: {doc:?}"));
232	            }
233	            if finish == Finish::ApproveAll {
234	                clock += 3000;
235	                let action = state.on_key_at(key(KeyCode::Char('a')), at(clock));
236	                let confirming = matches!(&state.overlay, Some(Overlay::Approval(approval)) if approval.confirming);
237	                if action.is_some() || !confirming {
238	                    out.push(format!("{tag}: `a` did not ask the question ({action:?})"));
239	                    return out;
240	                }
241	                // The question must be on screen before Enter can confirm it.
242	                frame = draw(&mut state, width, height, mode);
243	                check_answerable_frame(&frame, &format!("{tag} (question)"), &mut out);
244	                // A second press inside the wait is ignored with a notice; the question stays drawn.
245	                clock += 100;
246	                let action = state.on_key_at(key(KeyCode::Char('a')), at(clock));
247	                if action.is_some() {
248	                    out.push(format!("{tag}: a second `a` inside the wait answered ({action:?})"));
249	                    return out;
250	                }
251	                frame = draw(&mut state, width, height, mode);
252	                check_answerable_frame(&frame, &format!("{tag} (after a second `a`)"), &mut out);
253	                clock += 3000;
254	                let action = state.on_key_at(key(KeyCode::Enter), at(clock));
255	                if !is_approve(&action, true) {
256	                    out.push(format!("{tag}: Enter after the drawn question did not confirm ({action:?})"));
257	                }
258	                return out;
259	            }
260	            for burst in [vec!['x', 'y'], vec!['y', 'x'], vec!['a', 'a'], vec!['n', 'n']] {
261	                clock += 3000;
262	                let keys = burst.into_iter().map(|c| key(KeyCode::Char(c))).collect();
263	                let action = state.on_key_burst_at(keys, at(clock));
264	                if action.is_some() || !matches!(state.overlay, Some(Overlay::Approval(_))) {
265	                    out.push(format!("{tag}: a burst answered ({action:?})"));
266	                    return out;
267	                }
268	            }
269	            clock += 3000;
270	            let action = state.on_key_burst_at(vec![key(KeyCode::Enter), key(KeyCode::Enter)], at(clock));
271	            if action.is_some() {
272	                out.push(format!("{tag}: Enter, Enter in one burst answered ({action:?})"));
273	                return out;
274	            }
275	            clock += 3000;
276	            let action = state.on_key_at(key(KeyCode::Char('y')), at(clock));
277	            if !is_approve(&action, false) {
278	                out.push(format!("{tag}: y after reading everything did not approve ({action:?})"));
279	            }
280	            return out;
281	        }
282	        // Not everything was drawn yet: no decision key answers.
283	        clock += 3000;
284	        let action = state.on_key_at(key(KeyCode::Char('y')), at(clock));
285	        if action.is_some() {
286	            out.push(format!("{tag}: y answered before the change was drawn ({action:?})"));
287	            return out;
288	        }
289	        clock += 3000;
290	        state.on_key_at(key(KeyCode::PageDown), at(clock));
291	        frame = draw(&mut state, width, height, mode);
292	        if !answerable(&state) {
293	            out.push(format!("{tag}: stopped being answerable while reading"));
294	            return out;
295	        }
296	    }
297	    out.push(format!("{tag}: could not be read through to an answer"));
298	    out
299	}
300	
301	const WIDTHS: [u16; 5] = [20, 40, 41, 60, 61];
302	/// Every page of a change whose text is full of unsafe characters: none of them reaches a cell, wherever it is scrolled.
303	fn scan_every_page(kind: &Kind, width: u16, height: u16, mode: Mode) -> Vec<String> {
304	    let mut out = Vec::new();
305	    // The heading wraps the subject over many rows (and is drawn at the top whatever the page): a short one leaves room
306	    // for the pages.
307	    let kind = &Kind { subject: "x".to_string(), ..kind.clone() };
308	    let mut state = build(kind, "", false);
309	    let mut frame = draw(&mut state, width, height, mode);
310	    let tag = format!("{} / {width}x{height}", kind.name);
311	    for page in 0..120 {
312	        for row in &frame.rows {
313	            if let Some(c) = row.chars().find(|c| forbidden(*c)) {
314	                out.push(format!("{tag} page {page}: U+{:04X} is on screen", c as u32));
315	            }
316	        }
317	        let layout = frame.layout;
318	        if layout.approval_top + layout.overlay_rows >= layout.approval_total {
319	            return out;
320	        }
321	        state.on_key_at(key(KeyCode::PageDown), Instant::now());
322	        frame = draw(&mut state, width, height, mode);
323	    }
324	    out.push(format!("{tag}: the pages never ended"));
325	    out
326	}
327	
328	const READ_WIDTHS: [u16; 3] = [20, 40, 60];
329	const SCREEN_WIDTHS: [u16; 4] = [20, 40, 60, 100];
330	
331	fn sweep_kind(kind: &Kind, with_bad: bool, mode: Mode) -> Vec<String> {
332	    let mut out = Vec::new();
333	    // Drafts and the queue matter on the whole screen (the draft takes rows); the panel alone only shows the queue.
334	    let queue = matches!(kind.name, "command" | "patch");
335	    let drafts: &[(&str, &str, bool)] = match (mode, with_bad, queue) {
336	        (Mode::Panel, true, _) | (Mode::Screen, true, _) => &[("empty", "", false)],
337	        (Mode::Panel, false, true) => &[("empty", "", false), ("queued", "", true)],
338	        (Mode::Panel, false, false) => &[("empty", "", false)],
339	        (Mode::Screen, false, true) => &[("empty", "", false), ("multiline", "one\ntwo\nthree", false), ("queued", "", true)],
340	        (Mode::Screen, false, false) => &[("empty", "", false), ("multiline", "one\ntwo\nthree", false)],
341	    };
342	    // Text with unsafe characters is drawn at a few sizes only: how a character is shown does not depend on the size.
343	    let (widths, max_height): (&[u16], u16) = match (mode, with_bad) {
344	        (Mode::Panel, false) => (&WIDTHS, 20),
345	        (_, true) => (&[20, 60], 12),
346	        (Mode::Screen, false) => (&SCREEN_WIDTHS, 20),
347	    };
348	    for &(label, draft, queued) in drafts {
349	        for &width in widths {
350	            let mut was_answerable = false;
351	            for height in 1..=max_height {
352	                let tag = format!("{} / {mode_name} / {label} / {width}x{height}", kind.name, mode_name = if mode == Mode::Panel { "panel" } else { "screen" });
353	                let mut state = build(kind, draft, queued);
354	                let frame = draw(&mut state, width, height, mode);
355	                // (a) and (d): what is on the screen.
356	                for row in &frame.rows {
357	                    if unicode_width::UnicodeWidthStr::width(row.as_str()) > usize::from(width) {
358	                        out.push(format!("{tag}: a row is wider than the terminal"));
359	                    }
360	                    if let Some(c) = row.chars().find(|c| forbidden(*c)) {
361	                        out.push(format!("{tag}: U+{:04X} is on screen", c as u32));
362	                    }
363	                }
364	                // Ratatui leaves zero-width characters out of its cells, so a cell check alone cannot see them: the text the
365	                // panel draws from must be free of them as well.
366	                if let Some(Overlay::Approval(approval)) = &state.overlay
367	                    && let Some(row) = approval.lines.iter().find(|row| row.text.chars().any(forbidden))
368	                {
369	                    out.push(format!("{tag}: a row of the panel's text still holds an unsafe character: {:?}", row.text));
370	                }
371	                let body = frame.layout.approval_body;
372	                if body.right() > width || body.bottom() > height {
373	                    out.push(format!("{tag}: the change's rows are outside the terminal"));
374	                }
375	                let shown = answerable(&state);
376	                // (c): monotonic in height, and a one-line command fits where it plainly can.
377	                if was_answerable && !shown {
378	                    out.push(format!("{tag}: answerable at a smaller height, refused here"));
379	                }
380	                was_answerable |= shown;
381	                // Panel: border, heading and its subtitle, buttons, hint, one row. Screen: the same above a one-row
382	                // status line and the three-row composer.
383	                let room = if mode == Mode::Panel { 7 } else { 11 };
384	                if !with_bad && kind.name == "command" && label == "empty" && width >= 60 && height >= room && !shown {
385	                    out.push(format!("{tag}: a one-line command is refused on a terminal with room for it"));
386	                }
387	                if shown {
388	                    check_answerable_frame(&frame, &tag, &mut out);
389	                } else {
390	                    let all = flat(&frame.rows.join(""));
391	                    let top = frame.rows.iter().position(|row| row.contains('╭'));
392	                    let bottom = frame.rows.iter().position(|row| row.contains('╰'));
393	                    if let (Some(top), Some(bottom)) = (top, bottom)
394	                        && bottom >= top + 2
395	                        && !all.contains("enlarge")
396	                    {
397	                        out.push(format!("{tag}: refused without saying to enlarge the terminal:\n{}", frame.rows.join("\n")));
398	                    }
399	                    for code in ['y', 'a'] {
400	                        if let Some(action) = state.on_key_at(key(KeyCode::Char(code)), Instant::now() + Duration::from_secs(60)) {
401	                            out.push(format!("{tag}: {code} answered a panel that was not drawn ({action:?})"));
402	                        }
403	                    }
404	                    let action = state.on_key_at(key(KeyCode::Enter), Instant::now() + Duration::from_secs(120));
405	                    if action.is_some() {
406	                        out.push(format!("{tag}: Enter answered a panel that was not drawn ({action:?})"));
407	                    }
408	                }
409	                // Esc denies wherever the panel stands.
410	                let mut fresh = build(kind, draft, queued);
411	                if !matches!(fresh.on_key_at(key(KeyCode::Esc), Instant::now()), Some(Action::Send(Command::Deny { .. }))) {
412	                    out.push(format!("{tag}: Esc did not deny"));
413	                }
414	                // (b), (e): reading through to an answer. The panel alone: every kind at the widths that wrap differently; the
415	                // whole screen: the commands, with and without a draft.
416	                let reads = match mode {
417	                    Mode::Panel => label == "empty",
418	                    Mode::Screen => matches!(kind.name, "command" | "command multi") && matches!(label, "empty" | "multiline"),
419	                };
420	                if !with_bad && reads && height <= 18 && READ_WIDTHS.contains(&width) {
421	                    out.extend(read_through(kind, draft, queued, width, height, mode, Finish::Approve, &tag));
422	                    if matches!(kind.name, "command multi" | "patch") && label == "empty" {
423	                        out.extend(read_through(kind, draft, queued, width, height, mode, Finish::ApproveAll, &format!("{tag} (all later)")));
424	                    }
425	                }
426	            }
427	        }
428	    }
429	    out
430	}
431	
432	#[test]
433	fn the_approval_panel_holds_its_invariants_across_its_whole_state_space() {
434	    let started = Instant::now();
435	    let clean = kinds("");
436	    let dirty = kinds(&bad());
437	    let violations: Vec<String> = std::thread::scope(|scope| {
438	        let mut handles = Vec::new();
439	        for kind in &dirty {
440	            for (width, height) in [(100u16, 30u16), (60, 45)] {
441	                handles.push(scope.spawn(move || scan_every_page(kind, width, height, Mode::Panel)));
442	            }
443	        }
444	        for (kinds, with_bad) in [(&clean, false), (&dirty, true)] {
445	            for kind in kinds {
446	                for mode in [Mode::Panel, Mode::Screen] {
447	                    handles.push(scope.spawn(move || sweep_kind(kind, with_bad, mode)));
448	                }
449	            }
450	        }
451	        handles.into_iter().flat_map(|handle| handle.join().expect("the sweep must not panic")).collect()
452	    });
453	    // Grouped by what went wrong, with the first example of each.
454	    let mut groups: BTreeMap<String, (usize, &String)> = BTreeMap::new();
455	    for violation in &violations {
456	        let class = violation.split_once(": ").map_or(violation.as_str(), |(_, what)| what).chars().take(60).collect::<String>();
457	        groups.entry(class).or_insert((0, violation)).0 += 1;
458	    }
459	    let report: Vec<String> = groups.iter().map(|(class, (count, first))| format!("{count} x {class}\n    e.g. {first}")).collect();
460	    assert!(violations.is_empty(), "{} violations in {:?}:\n{}", violations.len(), started.elapsed(), report.join("\n"));
461	}
462	
